package com.hms.social;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="social_connections") public class SocialConnection { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false) private SocialPlatform platform; @Column(nullable=false,length=180) private String handle; @Column(length=500) private String profileUrl; @Column(nullable=false) private boolean enabled; private OffsetDateTime lastSyncedAt; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected SocialConnection(){} public SocialConnection(UUID tenantId,CreateSocialConnectionRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.platform=r.platform();this.handle=r.handle().trim();this.profileUrl=r.profileUrl();this.enabled=true;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public SocialPlatform getPlatform(){return platform;} public String getHandle(){return handle;} public String getProfileUrl(){return profileUrl;} public boolean isEnabled(){return enabled;} }
